def max_window_sum(nums: list[int], k: int) -> int | None:
    if k <= 0 or k > len(nums):
        return None
    current = sum(nums[:k])
    best = current
    for right in range(k, len(nums)):
        current += nums[right] - nums[right - k]
        best = max(best, current)
    return best

