#include <algorithm>
#include <optional>
#include <vector>
using namespace std;
optional<int> max_window_sum(const vector<int>& nums, int k) {
    if (k <= 0 || k > static_cast<int>(nums.size())) return nullopt;
    int current = 0;
    for (int i = 0; i < k; ++i) current += nums[i];
    int best = current;
    for (int right = k; right < static_cast<int>(nums.size()); ++right) {
        current += nums[right] - nums[right-k];
        best = max(best, current);
    }
    return best;
}

