def is_anagram(first: str, second: str) -> bool:
    if len(first) != len(second):
        return False
    counts = [0] * 26
    for left, right in zip(first, second):
        counts[ord(left) - ord('a')] += 1
        counts[ord(right) - ord('a')] -= 1
    return all((count == 0 for count in counts))

