def num_islands(g):
    if not g:
        return 0
    R, C = (len(g), len(g[0]))
    seen = set()
    n = 0
    for r in range(R):
        for c in range(C):
            if g[r][c] == '1' and (r, c) not in seen:
                n += 1
                seen.add((r, c))
                st = [(r, c)]
                while st:
