def num_islands(g):
    if not g:
        return 0
    R, C = (len(g), len(g[0]))
    seen = set()
    n = 0
    for r in range(R):
        for c in range(C):
            if g[r][c] == '1' and (r, c) not in seen:
                n += 1
                seen.add((r, c))
                st = [(r, c)]
                while st:
                    x, y = st.pop()
                    for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                        if 0 <= a < R and 0 <= b < C and (g[a][b] == '1') and ((a, b) not in seen):
                            seen.add((a, b))
                            st.append((a, b))
    return n

