bool can_finish(int n,const vector<vector<int>>& e) {
    vector<vector<int>> g(n);
    vector<int>d(n);
    for(auto x:e)g[x[1]].push_back(x[0]),++d[x[0]];
    queue<int>q;
    for(int i=0;i<n;i++)if(!d[i])q.push(i);
    int done=0;
    while(!q.empty()) {
        int x=q.front();
        q.pop();
        ++done;
        for(int y:g[x])if(--d[y]==0)q.push(y);
    }
    return done==n;
}

