def word_ladder(begin, end, words):
    if begin == end:
        return 1
    allowed = {word for word in words if len(word) == len(begin)}
    if end not in allowed:
        return 0
    q = deque([(begin, 1)])
    seen = {begin}
    while q:
        word, d = q.popleft()
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nxt = word[:i] + c + word[i + 1:]
                if nxt == end:
                    return d + 1
                if nxt in allowed and nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))
    return 0

