import heapq

def network_delay(edges, n, k):
    g = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        g[u].append((v, w))
    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    h = [(0, k)]
    while h:
        d, u = heapq.heappop(h)
        if d != dist[u]:
            continue
        for v, w in g[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(h, (nd, v))
    ans = max(dist[1:])
    return -1 if ans == float('inf') else ans

